// Parsea la respuesta del LLM y busca un pictograma ARASAAC por actividad
const body = $('Webhook').first().json.body || {};
const raw = $json.choices[0].message.content;
const d = JSON.parse(raw);
d.alumno = d.alumno || body.alumno || null;
d.fecha = d.fecha || new Date().toISOString().slice(0,10);

for (const a of (d.actividades || [])) {
  const kw = encodeURIComponent((a.palabra_clave || a.actividad || '').toLowerCase());
  try {
    const res = await this.helpers.httpRequest({ url: `https://api.arasaac.org/api/pictograms/es/search/${kw}`, json: true });
    const id = Array.isArray(res) && res.length ? res[0]._id : null;
    a.picto_id = id;
    a.picto_url = id ? `https://static.arasaac.org/pictograms/${id}/${id}_500.png` : null;
  } catch (e) { a.picto_id = null; a.picto_url = null; }
}

// Mensaje listo para WhatsApp / mail a la familia
const alertas = (d.alertas || []).map(x => `⚠️ ${x.detalle}`).join('\n');
d.mensaje_familia = `Hola! Así fue el día de ${d.alumno} 🌈\n\n${d.resumen_familia}` + (alertas ? `\n\n${alertas}` : '') + (d.logros?.length ? `\n\n⭐ Logros: ${d.logros.join(', ')}` : '');
return [{ json: d }];
